-- null when the name is fine, else 'length' | 'chars' | 'blocked'.
create or replace function private.tag_problem(name text) returns text
language plpgsql stable set search_path = '' as $$
declare
  k text;
  words text[];
begin
  if name is null or char_length(name) < 3 or char_length(name) > 18 then
    return 'length';
  end if;
  if name !~ '^[A-Za-zÀ-ÖØ-öø-ÿ]+([ -][A-Za-zÀ-ÖØ-öø-ÿ]+)*$' then
    return 'chars';
  end if;
  k := private.tag_key(name);
  if char_length(k) < 3 then
    return 'length';
  end if;
  select array_agg(private.rot13(private.tag_key(w))) into words
  from regexp_split_to_table(name, '[ -]+') as w;
  if exists (
    select 1 from private.blocked_name_terms b
    where (b.anywhere and strpos(private.rot13(k), b.term_rot13) > 0)
       or b.term_rot13 = private.rot13(k)
       or b.term_rot13 = any (words)
  ) then
    return 'blocked';
  end if;
  return null;
end
$$;

-- ------------------------------------------------------------------ profiles
create table if not exists public.profiles (
  id uuid primary key references auth.users (id) on delete cascade,
  gamertag text not null,
  gamertag_key text not null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create unique index if not exists profiles_gamertag_key on public.profiles (gamertag_key);

-- Every insert or rename is checked and gets its key here, whoever sends it.
create or replace function private.profiles_before_write() returns trigger
language plpgsql security definer set search_path = '' as $$
declare
  problem text;
begin
  new.gamertag := regexp_replace(btrim(new.gamertag), '\s+', ' ', 'g');
  problem := private.tag_problem(new.gamertag);
  if problem is not null then
    raise exception 'gamertag_%', problem using errcode = 'check_violation';
  end if;
  new.gamertag_key := private.tag_key(new.gamertag);
  if tg_op = 'UPDATE' then
    new.id := old.id;
    new.created_at := old.created_at;
  else
    new.created_at := now();
  end if;
  new.updated_at := now();
  return new;
end
$$;

drop trigger if exists profiles_before_write on public.profiles;
create trigger profiles_before_write
  before insert or update on public.profiles
  for each row execute function private.profiles_before_write();

-- Row Level Security: gamertags are public (leaderboards, friend search);
-- you can only create and rename your own; nobody deletes through the API
-- (deleting the account removes the profile).
alter table public.profiles enable row level security;

revoke all on public.profiles from anon, authenticated;
grant select on public.profiles to anon, authenticated;
grant insert (id, gamertag), update (gamertag) on public.profiles to authenticated;

drop policy if exists "Gamertags are public" on public.profiles;
create policy "Gamertags are public" on public.profiles
  for select to anon, authenticated using (true);

drop policy if exists "Riders create their own profile" on public.profiles;
create policy "Riders create their own profile" on public.profiles
  for insert to authenticated with check ((select auth.uid()) = id);

drop policy if exists "Riders rename only themselves" on public.profiles;
create policy "Riders rename only themselves" on public.profiles
  for update to authenticated
  using ((select auth.uid()) = id) with check ((select auth.uid()) = id);

-- Live availability check while typing:
-- 'ok' | 'yours' | 'taken' | 'length' | 'chars' | 'blocked'.
create or replace function public.gamertag_status(name text) returns text
language plpgsql stable security definer set search_path = '' as $$
declare
  tag text := regexp_replace(btrim(coalesce(name, '')), '\s+', ' ', 'g');
  problem text;
  owner uuid;
begin
  problem := private.tag_problem(tag);
  if problem is not null then
    return problem;
  end if;
  select p.id into owner from public.profiles p where p.gamertag_key = private.tag_key(tag);
  if owner is null then
    return 'ok';
  elsif owner = auth.uid() then
    return 'yours';
  end if;
  return 'taken';
end
$$;

revoke all on function public.gamertag_status(text) from public;
grant execute on function public.gamertag_status(text) to anon, authenticated;
revoke all on all functions in schema private from public, anon, authenticated;

-- =================================================================== 20261108120100_saves.sql

-- CranSki · Phase 3 · Step 2: cloud saves.
--
-- One row per account holding the things that follow you between devices:
-- settings (camera, sound, stats overlay, key and controller bindings), personal
-- bests per park, and Locker choices. Graphics level, frame cap and the touch
-- layout stay on each device.
--
-- Personal bests here are your own record, not leaderboard scores: only the
-- submit-run Edge Function (step 4) can write leaderboard scores.

create table if not exists public.saves (
  user_id uuid primary key references auth.users (id) on delete cascade,
  settings jsonb,
  settings_at timestamptz,
  locker jsonb,
  locker_at timestamptz,
  bests jsonb not null default '{}'::jsonb,
  updated_at timestamptz not null default now(),
  constraint saves_settings_size check (settings is null or (jsonb_typeof(settings) = 'object' and pg_column_size(settings) < 32768)),
  constraint saves_locker_size check (locker is null or (jsonb_typeof(locker) = 'object' and pg_column_size(locker) < 8192)),
  constraint saves_bests_shape check (jsonb_typeof(bests) = 'object' and pg_column_size(bests) < 4096)
);

-- Keep only "park id -> whole number of points" pairs, taking the higher of
-- the two values for each park.
create or replace function private.merge_bests(a jsonb, b jsonb) returns jsonb
language sql immutable set search_path = '' as $$
  select coalesce(jsonb_object_agg(k, v), '{}'::jsonb)
  from (
    select k, max(v) as v
    from (
      select key as k, (value #>> '{}')::numeric as v
      from jsonb_each(coalesce(a, '{}'::jsonb) || '{}'::jsonb)
      where key ~ '^[a-z]{2,16}$' and jsonb_typeof(value) = 'number'
      union all
      select key, (value #>> '{}')::numeric
      from jsonb_each(case when jsonb_typeof(b) = 'object' then b else '{}'::jsonb end)
      where key ~ '^[a-z]{2,16}$' and jsonb_typeof(value) = 'number'
    ) x
    where v >= 0 and v <= 100000000
    group by k
    limit 64
  ) y
$$;

-- Row Level Security: you can only ever see and change your own save.
alter table public.saves enable row level security;

revoke all on public.saves from anon, authenticated;
grant select on public.saves to authenticated;

drop policy if exists "Riders read their own save" on public.saves;
create policy "Riders read their own save" on public.saves
  for select to authenticated using ((select auth.uid()) = user_id);

-- Writes go through sync_save, which merges instead of overwriting:
-- settings and Locker keep whichever side changed last, bests keep the
-- higher score for each park. It returns the merged save.
create or replace function public.sync_save(
  p_settings jsonb default null,
  p_settings_at timestamptz default null,
  p_locker jsonb default null,
  p_locker_at timestamptz default null,
  p_bests jsonb default null
) returns public.saves
language plpgsql security definer set search_path = '' as $$
declare
  me uuid := auth.uid();
  row public.saves;
begin
  if me is null then
    raise exception 'not signed in' using errcode = '42501';
  end if;
  if p_settings is not null and jsonb_typeof(p_settings) <> 'object' then p_settings := null; end if;
  if p_locker is not null and jsonb_typeof(p_locker) <> 'object' then p_locker := null; end if;
  -- A clock far in the future can't pin a save forever.
  if p_settings_at > now() + interval '1 day' then p_settings_at := now(); end if;
  if p_locker_at > now() + interval '1 day' then p_locker_at := now(); end if;

  insert into public.saves (user_id) values (me) on conflict (user_id) do nothing;
  select * into row from public.saves s where s.user_id = me for update;

  if p_settings is not null and p_settings_at is not null and (row.settings_at is null or p_settings_at > row.settings_at) then
    row.settings := p_settings;
    row.settings_at := p_settings_at;
  end if;
  if p_locker is not null and p_locker_at is not null and (row.locker_at is null or p_locker_at > row.locker_at) then
    row.locker := p_locker;
    row.locker_at := p_locker_at;
  end if;
  row.bests := private.merge_bests(row.bests, p_bests);
  row.updated_at := now();

  update public.saves s
  set settings = row.settings, settings_at = row.settings_at,
      locker = row.locker, locker_at = row.locker_at,
      bests = row.bests, updated_at = row.updated_at
  where s.user_id = me;
  return row;
end
$$;

revoke all on function public.sync_save(jsonb, timestamptz, jsonb, timestamptz, jsonb) from public, anon;
grant execute on function public.sync_save(jsonb, timestamptz, jsonb, timestamptz, jsonb) to authenticated;
revoke all on all functions in schema private from public, anon, authenticated;

-- =================================================================== 20261108120200_friends.sql

-- CranSki · Phase 3 · Step 3: friends and online status.
--
-- Rules (DESIGN.md, Safety): friends see your location only once you've
-- accepted each other. Pending requests show a gamertag and nothing else.
--
-- The tables are read and written only through the functions below, which
-- always act as the signed-in rider (auth.uid()).

-- ------------------------------------------------------------------ friendships
create table if not exists public.friendships (
  requester uuid not null references public.profiles (id) on delete cascade,
  addressee uuid not null references public.profiles (id) on delete cascade,
  status text not null default 'pending' check (status in ('pending', 'accepted')),
  created_at timestamptz not null default now(),
  accepted_at timestamptz,
  primary key (requester, addressee),
  constraint friendships_not_self check (requester <> addressee)
);
-- One row per pair, whichever way round the request went.
create unique index if not exists friendships_pair
  on public.friendships (least(requester, addressee), greatest(requester, addressee));
create index if not exists friendships_addressee on public.friendships (addressee);

alter table public.friendships enable row level security;
revoke all on public.friendships from anon, authenticated;
grant select on public.friendships to authenticated;

drop policy if exists "Riders see their own friendships" on public.friendships;
create policy "Riders see their own friendships" on public.friendships
  for select to authenticated
  using ((select auth.uid()) in (requester, addressee));

-- ------------------------------------------------------------------ presence
-- Where each signed-in rider is right now. Nobody can read this table
-- directly except for their own row: friends get it through my_friends(),
-- which only includes accepted friends.
create table if not exists public.presence (
  user_id uuid primary key references public.profiles (id) on delete cascade,
  location text not null check (location in ('basecamp', 'lift', 'riding', 'replay')),
  park text check (park ~ '^[a-z]{2,16}$'),
  seen_at timestamptz not null default now()
);

alter table public.presence enable row level security;
revoke all on public.presence from anon, authenticated;
grant select on public.presence to authenticated;

drop policy if exists "Riders see only their own presence row" on public.presence;
create policy "Riders see only their own presence row" on public.presence
  for select to authenticated using ((select auth.uid()) = user_id);

-- Fast "gamertag starts with" search.
create index if not exists profiles_gamertag_prefix on public.profiles (gamertag_key text_pattern_ops);

-- ------------------------------------------------------------------ functions

-- Find riders by gamertag (ignoring case, spaces and dashes). Signed-in only.
create or replace function public.search_riders(q text)
returns table (id uuid, gamertag text, relation text)
language sql stable security definer set search_path = '' as $$
  select p.id, p.gamertag,
    coalesce((
      select case
        when f.status = 'accepted' then 'friend'
        when f.requester = (select auth.uid()) then 'outgoing'
        else 'incoming' end
      from public.friendships f
      where (f.requester = (select auth.uid()) and f.addressee = p.id)
         or (f.requester = p.id and f.addressee = (select auth.uid()))
    ), 'none')
  from public.profiles p
  where (select auth.uid()) is not null
    and char_length(private.tag_key(q)) >= 2
    and p.gamertag_key like private.tag_key(q) || '%'
    and p.id <> (select auth.uid())
  order by (p.gamertag_key = private.tag_key(q)) desc, char_length(p.gamertag_key), p.gamertag_key
  limit 10
$$;

-- Ask someone to be friends. If they already asked you, you're now friends.
-- Returns 'requested' | 'accepted' | 'friends' | 'self' | 'unknown' |
-- 'no_gamertag' | 'too_many'.
create or replace function public.send_friend_request(target uuid) returns text
language plpgsql security definer set search_path = '' as $$
declare
  me uuid := auth.uid();
  existing public.friendships;
begin
  if me is null then
    raise exception 'not signed in' using errcode = '42501';
  end if;
  if target = me then return 'self'; end if;
  if not exists (select 1 from public.profiles where id = me) then return 'no_gamertag'; end if;
  if not exists (select 1 from public.profiles where id = target) then return 'unknown'; end if;

  select * into existing from public.friendships f
  where (f.requester = me and f.addressee = target) or (f.requester = target and f.addressee = me);
  if found then
    if existing.status = 'accepted' then return 'friends'; end if;
    if existing.requester = me then return 'requested'; end if;
    update public.friendships set status = 'accepted', accepted_at = now()
    where requester = target and addressee = me;
    return 'accepted';
  end if;

  if (select count(*) from public.friendships where requester = me and status = 'pending') >= 50
     or (select count(*) from public.friendships where me in (requester, addressee) and status = 'accepted') >= 200 then
    return 'too_many';
  end if;
  insert into public.friendships (requester, addressee) values (me, target);
  return 'requested';
exception when unique_violation then
  return 'requested';
end
$$;

-- Accept or decline a request someone sent you. Returns 'friends' |
-- 'declined' | 'gone'.
create or replace function public.respond_friend_request(other uuid, accept boolean) returns text
language plpgsql security definer set search_path = '' as $$
declare
  me uuid := auth.uid();
begin
  if me is null then
    raise exception 'not signed in' using errcode = '42501';
  end if;
  if accept then
    update public.friendships set status = 'accepted', accepted_at = now()
    where requester = other and addressee = me and status = 'pending';
    return case when found then 'friends' else 'gone' end;
  end if;
  delete from public.friendships where requester = other and addressee = me and status = 'pending';
  return case when found then 'declined' else 'gone' end;
end
$$;

-- Cancel a request you sent, or unfriend someone.
create or replace function public.remove_friend(other uuid) returns text
language plpgsql security definer set search_path = '' as $$
declare
  me uuid := auth.uid();
begin
  if me is null then
    raise exception 'not signed in' using errcode = '42501';
  end if;
  delete from public.friendships
  where (requester = me and addressee = other) or (requester = other and addressee = me);
  return case when found then 'removed' else 'gone' end;
end
$$;

-- Your friends and requests. Online status and location are only filled in
-- for accepted friends who were seen in the last 90 seconds.
create or replace function public.my_friends()
returns table (id uuid, gamertag text, relation text, online boolean, location text, park text, since timestamptz)
language sql stable security definer set search_path = '' as $$
  with mine as (
    select f.*, case when f.requester = (select auth.uid()) then f.addressee else f.requester end as other
    from public.friendships f
    where (select auth.uid()) in (f.requester, f.addressee)
  )
  select p.id, p.gamertag,
    case when m.status = 'accepted' then 'friend'
         when m.addressee = (select auth.uid()) then 'incoming'
         else 'outgoing' end as relation,
    coalesce(m.status = 'accepted' and pr.seen_at > now() - interval '90 seconds', false) as online,
    case when m.status = 'accepted' and pr.seen_at > now() - interval '90 seconds' then pr.location end,
    case when m.status = 'accepted' and pr.seen_at > now() - interval '90 seconds' then pr.park end,
    coalesce(m.accepted_at, m.created_at)
  from mine m
  join public.profiles p on p.id = m.other
  left join public.presence pr on pr.user_id = m.other
  order by relation, online desc, p.gamertag_key
$$;

-- "I'm here": called when your location changes and every ~45 s while the
-- game is open. Does nothing until you have a gamertag.
create or replace function public.heartbeat(p_location text, p_park text default null) returns void
language plpgsql security definer set search_path = '' as $$
declare
  me uuid := auth.uid();
begin
  if me is null or not exists (select 1 from public.profiles where id = me) then
    return;
  end if;
  if p_location is null or p_location not in ('basecamp', 'lift', 'riding', 'replay') then
    p_location := 'basecamp';
  end if;
  if p_park is not null and p_park !~ '^[a-z]{2,16}$' then
    p_park := null;
  end if;
  insert into public.presence (user_id, location, park, seen_at)
  values (me, p_location, case when p_location = 'basecamp' then null else p_park end, now())
  on conflict (user_id) do update
    set location = excluded.location, park = excluded.park, seen_at = excluded.seen_at;
end
$$;

-- Appear offline / signing out.
create or replace function public.go_offline() returns void
language sql security definer set search_path = '' as $$
  delete from public.presence where user_id = (select auth.uid())
$$;

do $$
declare
  fn text;
begin
  foreach fn in array array[
    'public.search_riders(text)',
    'public.send_friend_request(uuid)',
    'public.respond_friend_request(uuid, boolean)',
    'public.remove_friend(uuid)',
    'public.my_friends()',
    'public.heartbeat(text, text)',
    'public.go_offline()'
  ] loop
    execute format('revoke all on function %s from public, anon', fn);
    execute format('grant execute on function %s to authenticated', fn);
  end loop;
end
$$;
revoke all on all functions in schema private from public, anon, authenticated;

-- =================================================================== 20261108120300_leaderboards.sql

-- CranSki · Phase 3 · Step 4: per-park leaderboards, checked by the server.
--
-- A run is submitted as its recorded inputs. The submit-run Edge Function
-- re-rides those inputs through the same deterministic simulation the game
-- uses, and only if its score matches what the player saw does it save a
-- score, and the score it saves is the one it calculated itself.
--
-- Riders can read the boards (signed in or not) but can never write to them:
-- only the Edge Function, using the project's secret key on Supabase's
-- servers, can call record_score.

-- One row per rider per park: their best verified run.
create table if not exists public.leaderboard (
  park text not null check (park in ('bigair', 'yard', 'apex', 'forest', 'pipe', 'bellevue')),
  user_id uuid not null references public.profiles (id) on delete cascade,
  total integer not null check (total >= 0),
  run_time real,
  best_trick text,
  top_speed integer,
  airtime real,
  sim_version integer not null,
  achieved_at timestamptz not null default now(),
  primary key (park, user_id)
);
create index if not exists leaderboard_rank on public.leaderboard (park, total desc, achieved_at);

-- The inputs behind each leaderboard run, kept so a run can be re-checked or
-- watched later. Not readable through the API.
create table if not exists public.leaderboard_runs (
  park text not null,
  user_id uuid not null,
  steps integer not null,
  inputs text not null,
  marks jsonb not null default '[]'::jsonb,
  grab_slots jsonb not null,
  board boolean not null,
  sim_version integer not null,
  primary key (park, user_id),
  foreign key (park, user_id) references public.leaderboard (park, user_id) on delete cascade
);

-- Submissions per rider, for a simple rate limit.
create table if not exists private.submissions (
  user_id uuid not null references auth.users (id) on delete cascade,
  at timestamptz not null default now()
);
create index if not exists submissions_user_at on private.submissions (user_id, at);

-- ------------------------------------------------------------------ access
alter table public.leaderboard enable row level security;
alter table public.leaderboard_runs enable row level security;

revoke all on public.leaderboard from anon, authenticated;
revoke all on public.leaderboard_runs from anon, authenticated;
grant select on public.leaderboard to anon, authenticated;

drop policy if exists "Leaderboards are public" on public.leaderboard;
create policy "Leaderboards are public" on public.leaderboard
  for select to anon, authenticated using (true);
-- No insert/update/delete policies: riders can't write scores at all.

-- ------------------------------------------------------------------ server-only functions

-- Count a submission; false if this rider has sent too many recently.
create or replace function public.note_submission(p_user uuid) returns boolean
language plpgsql security definer set search_path = '' as $$
begin
  delete from private.submissions where at < now() - interval '1 day';
  if (select count(*) from private.submissions where user_id = p_user and at > now() - interval '10 minutes') >= 30 then
    return false;
  end if;
  insert into private.submissions (user_id) values (p_user);
  return true;
end
$$;

-- Save a verified score (keeping the rider's best) and return
-- { best, improved, rank }.
create or replace function public.record_score(
  p_user uuid,
  p_park text,
  p_total integer,
  p_time real,
  p_best_trick text,
  p_top_speed integer,
  p_airtime real,
  p_sim_version integer,
  p_steps integer,
  p_inputs text,
  p_marks jsonb,
  p_grab_slots jsonb,
  p_board boolean
) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  old_total integer;
  mine public.leaderboard;
  improved boolean;
  place bigint;
begin
  select total into old_total from public.leaderboard where park = p_park and user_id = p_user for update;
  improved := old_total is null or p_total > old_total;
  if improved then
    insert into public.leaderboard (park, user_id, total, run_time, best_trick, top_speed, airtime, sim_version, achieved_at)
    values (p_park, p_user, p_total, p_time, left(p_best_trick, 80), p_top_speed, p_airtime, p_sim_version, now())
    on conflict (park, user_id) do update set
      total = excluded.total, run_time = excluded.run_time, best_trick = excluded.best_trick,
      top_speed = excluded.top_speed, airtime = excluded.airtime, sim_version = excluded.sim_version,
      achieved_at = excluded.achieved_at;
    insert into public.leaderboard_runs (park, user_id, steps, inputs, marks, grab_slots, board, sim_version)
    values (p_park, p_user, p_steps, p_inputs, coalesce(p_marks, '[]'::jsonb), p_grab_slots, p_board, p_sim_version)
    on conflict (park, user_id) do update set
      steps = excluded.steps, inputs = excluded.inputs, marks = excluded.marks,
      grab_slots = excluded.grab_slots, board = excluded.board, sim_version = excluded.sim_version;
  end if;
  select * into mine from public.leaderboard where park = p_park and user_id = p_user;
  select 1 + count(*) into place from public.leaderboard l
  where l.park = p_park and (l.total > mine.total or (l.total = mine.total and l.achieved_at < mine.achieved_at));
  return jsonb_build_object('best', mine.total, 'improved', improved, 'rank', place);
end
$$;

revoke all on function public.note_submission(uuid) from public, anon, authenticated;
revoke all on function public.record_score(uuid, text, integer, real, text, integer, real, integer, integer, text, jsonb, jsonb, boolean) from public, anon, authenticated;
grant execute on function public.note_submission(uuid) to service_role;
grant execute on function public.record_score(uuid, text, integer, real, text, integer, real, integer, integer, text, jsonb, jsonb, boolean) to service_role;

-- ------------------------------------------------------------------ reading the boards

-- Top of a board, with gamertags.
create or replace function public.leaderboard_top(p_park text, p_limit integer default 50)
returns table (rank bigint, user_id uuid, gamertag text, total integer, best_trick text, achieved_at timestamptz)
language sql stable set search_path = '' as $$
  select row_number() over (order by l.total desc, l.achieved_at), l.user_id, p.gamertag, l.total, l.best_trick, l.achieved_at
  from public.leaderboard l join public.profiles p on p.id = l.user_id
  where l.park = p_park
  order by l.total desc, l.achieved_at
  limit least(greatest(p_limit, 1), 100)
$$;

-- Your own place on a board (null row if you haven't posted there).
create or replace function public.leaderboard_me(p_park text)
returns table (rank bigint, total integer, best_trick text, achieved_at timestamptz)
language sql stable set search_path = '' as $$
  select 1 + (select count(*) from public.leaderboard o
              where o.park = l.park and (o.total > l.total or (o.total = l.total and o.achieved_at < l.achieved_at))),
         l.total, l.best_trick, l.achieved_at
  from public.leaderboard l
  where l.park = p_park and l.user_id = (select auth.uid())
$$;

-- You and your accepted friends on a board, with your places on the full board.
create or replace function public.leaderboard_friends(p_park text)
returns table (rank bigint, user_id uuid, gamertag text, total integer, best_trick text, achieved_at timestamptz)
language sql stable security definer set search_path = '' as $$
  with ranked as (
    select l.*, row_number() over (order by l.total desc, l.achieved_at) as place
    from public.leaderboard l where l.park = p_park
  )
  select r.place, r.user_id, p.gamertag, r.total, r.best_trick, r.achieved_at
  from ranked r join public.profiles p on p.id = r.user_id
  where r.user_id = (select auth.uid())
     or exists (
       select 1 from public.friendships f
       where f.status = 'accepted'
         and ((f.requester = (select auth.uid()) and f.addressee = r.user_id)
           or (f.addressee = (select auth.uid()) and f.requester = r.user_id)))
  order by r.place
  limit 200
$$;

revoke all on function public.leaderboard_top(text, integer) from public;
revoke all on function public.leaderboard_me(text) from public;
revoke all on function public.leaderboard_friends(text) from public, anon;
grant execute on function public.leaderboard_top(text, integer) to anon, authenticated;
grant execute on function public.leaderboard_me(text) to authenticated;
grant execute on function public.leaderboard_friends(text) to authenticated;
revoke all on all functions in schema private from public, anon, authenticated;

-- =================================================================== 20261109120000_live_rooms.sql

-- CranSki · Phase 4 · Step 1: live rooms over Supabase Realtime.
--
-- Riders use private Realtime channels:
--   'lobby'                      who is in which room (presence), for picking a
--                                room and the rider counts on the park map;
--   'room:<park>:<number>'       positions, poses and tricks (broadcast) and the
--                                room's roster (presence).
-- Only signed-in riders with a gamertag may join, listen or send. Nothing sent
-- over these channels is stored.
--
-- Supabase already has Row Level Security switched on for realtime.messages;
-- these policies decide who may use which topics. Party rooms
-- ('room:<park>:p<party>') are opened up to party members in step 5.

drop policy if exists "cranski: riders listen in the lobby and rooms" on realtime.messages;
create policy "cranski: riders listen in the lobby and rooms" on realtime.messages
  for select to authenticated
  using (
    realtime.messages.extension in ('broadcast', 'presence')
    and (
      (select realtime.topic()) = 'lobby'
      or ((select realtime.topic()) ~ '^room:[a-z]+:[0-9]+$')
    )
    and exists (select 1 from public.profiles p where p.id = (select auth.uid()))
  );

drop policy if exists "cranski: riders send in the lobby and rooms" on realtime.messages;
create policy "cranski: riders send in the lobby and rooms" on realtime.messages
  for insert to authenticated
  with check (
    realtime.messages.extension in ('broadcast', 'presence')
    and (
      (select realtime.topic()) = 'lobby'
      or ((select realtime.topic()) ~ '^room:[a-z]+:[0-9]+$')
    )
    and exists (select 1 from public.profiles p where p.id = (select auth.uid()))
  );

-- =================================================================== 20261109120100_chat_safety.sql

-- CranSki · Phase 4 · Step 3: chat, with the Safety rules from DESIGN.md.
--
-- Chat messages are never stored. Riders can't send on chat channels at all:
-- every message goes through the chat Edge Function, which filters it, signs it
-- and broadcasts it to the room over Realtime. The database only keeps:
--   - each rider's strike count and mute time (no message text);
--   - reports, with the last 10 minutes of that room's messages, for
--     moderators (read them in the dashboard's Table Editor -> reports).

-- ------------------------------------------------------------------ strikes and mutes
create table if not exists private.chat_state (
  user_id uuid primary key references auth.users (id) on delete cascade,
  strikes integer not null default 0,
  strikes_at timestamptz,
  muted_until timestamptz,
  window_start timestamptz,
  window_count integer not null default 0
);

-- Before sending: muted? sending too fast (more than 5 messages in 8 seconds)?
create or replace function public.chat_gate(p_user uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  st private.chat_state;
begin
  insert into private.chat_state (user_id) values (p_user) on conflict (user_id) do nothing;
  select * into st from private.chat_state where user_id = p_user for update;
  if st.muted_until is not null and st.muted_until > now() then
    return jsonb_build_object('ok', false, 'reason', 'muted', 'until', st.muted_until);
  end if;
  if st.window_start is null or st.window_start < now() - interval '8 seconds' then
    update private.chat_state set window_start = now(), window_count = 1 where user_id = p_user;
  else
    if st.window_count >= 5 then
      return jsonb_build_object('ok', false, 'reason', 'slow');
    end if;
    update private.chat_state set window_count = window_count + 1 where user_id = p_user;
  end if;
  return jsonb_build_object('ok', true);
end
$$;

-- A filtered message adds a strike (a hate word adds 2). 3 strikes within 15
-- minutes mutes that rider's chat for 15 minutes.
create or replace function public.chat_strike(p_user uuid, p_weight integer) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  st private.chat_state;
begin
  insert into private.chat_state (user_id) values (p_user) on conflict (user_id) do nothing;
  select * into st from private.chat_state where user_id = p_user for update;
  if st.strikes_at is null or st.strikes_at < now() - interval '15 minutes' then
    st.strikes := 0;
  end if;
  st.strikes := st.strikes + greatest(0, least(p_weight, 3));
  st.strikes_at := now();
  if st.strikes >= 3 then
    st.muted_until := now() + interval '15 minutes';
    st.strikes := 0;
  end if;
  update private.chat_state set strikes = st.strikes, strikes_at = st.strikes_at, muted_until = st.muted_until where user_id = p_user;
  return jsonb_build_object('muted_until', case when st.muted_until > now() then st.muted_until end);
end
$$;

-- So the game can show "you can chat again in N minutes".
create or replace function public.my_chat_mute() returns timestamptz
language sql stable security definer set search_path = '' as $$
  select muted_until from private.chat_state
  where user_id = (select auth.uid()) and muted_until > now()
$$;

-- ------------------------------------------------------------------ reports
create table if not exists public.reports (
  id bigint generated always as identity primary key,
  reporter uuid not null references auth.users (id) on delete cascade,
  reported uuid not null references auth.users (id) on delete cascade,
  topic text not null,
  reason text not null check (reason in ('hate', 'bullying', 'sexual', 'spam', 'name', 'cheating', 'other')),
  note text,
  messages jsonb not null default '[]'::jsonb,
  status text not null default 'open' check (status in ('open', 'actioned', 'dismissed')),
  created_at timestamptz not null default now()
);
create index if not exists reports_open on public.reports (status, created_at);

-- Only moderators (the dashboard) can read reports; riders can't read or write
-- them directly.
alter table public.reports enable row level security;
revoke all on public.reports from anon, authenticated;

-- Called by the chat Edge Function with the messages it has verified.
-- At most 10 reports an hour per rider.
create or replace function public.submit_report(
  p_reporter uuid, p_reported uuid, p_topic text, p_reason text, p_note text, p_messages jsonb
) returns jsonb
language plpgsql security definer set search_path = '' as $$
begin
  if (select count(*) from public.reports where reporter = p_reporter and created_at > now() - interval '1 hour') >= 10 then
    return jsonb_build_object('ok', false, 'error', 'slow_down');
  end if;
  insert into public.reports (reporter, reported, topic, reason, note, messages)
  values (p_reporter, p_reported, p_topic, p_reason, nullif(p_note, ''), coalesce(p_messages, '[]'::jsonb));
  return jsonb_build_object('ok', true);
end
$$;

revoke all on function public.chat_gate(uuid) from public, anon, authenticated;
revoke all on function public.chat_strike(uuid, integer) from public, anon, authenticated;
revoke all on function public.submit_report(uuid, uuid, text, text, text, jsonb) from public, anon, authenticated;
grant execute on function public.chat_gate(uuid) to service_role;
grant execute on function public.chat_strike(uuid, integer) to service_role;
grant execute on function public.submit_report(uuid, uuid, text, text, text, jsonb) to service_role;
revoke all on function public.my_chat_mute() from public, anon;
grant execute on function public.my_chat_mute() to authenticated;
revoke all on all functions in schema private from public, anon, authenticated;

-- ------------------------------------------------------------------ chat channels
-- Riders in rooms may LISTEN on 'chat:<park>:<room>'. There is deliberately no
-- insert policy: only the chat Edge Function (secret key) can send there.
drop policy if exists "cranski: riders listen to room chat" on realtime.messages;
create policy "cranski: riders listen to room chat" on realtime.messages
  for select to authenticated
  using (
    realtime.messages.extension = 'broadcast'
    and (select realtime.topic()) ~ '^chat:[a-z]+:[0-9]+$'
    and exists (select 1 from public.profiles p where p.id = (select auth.uid()))
  );

-- =================================================================== 20261109120200_duels.sql

-- CranSki · Phase 4 · Step 4: friendly 1v1 duels.
--
-- The two riders talk over a private Realtime channel 'duel:<random id>'
-- (whose turn it is, the 3-2-1, the live pose of whoever is riding, and each
-- finished run's recorded inputs, which the other rider re-rides to check the
-- score). Only signed-in riders with a gamertag can use duel channels, and the
-- id is random and only shared between the two riders. Nothing is stored.

drop policy if exists "cranski: riders listen in duels" on realtime.messages;
create policy "cranski: riders listen in duels" on realtime.messages
  for select to authenticated
  using (
    realtime.messages.extension in ('broadcast', 'presence')
    and (select realtime.topic()) ~ '^duel:[0-9a-f-]{36}$'
    and exists (select 1 from public.profiles p where p.id = (select auth.uid()))
  );

drop policy if exists "cranski: riders send in duels" on realtime.messages;
create policy "cranski: riders send in duels" on realtime.messages
  for insert to authenticated
  with check (
    realtime.messages.extension in ('broadcast', 'presence')
    and (select realtime.topic()) ~ '^duel:[0-9a-f-]{36}$'
    and exists (select 1 from public.profiles p where p.id = (select auth.uid()))
  );
